entries[216486] = { ["name"] = "Schockgeschmiedete Beinplatten", ["text"] = "Wird beim Aufheben gebunden\nBeine Platte\n420 Rüstung\n+8 Ausdauer\n+12 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 22.\n\nSchockgeschmiedete Kriegsplatte (0/3)\nSchockgeschmiedete Beinplatten\nSchockgeschmiedete Brustplatte\nSchockgeschmiedete Kampfstiefel\n(2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht die kritische Trefferchance Eures Zaubers 'Heiliger Schock' um 2%." }
