entries[216635] = { ["name"] = "Erschöpfter Leerenkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Mit einer angemessenen Energiequelle kombinieren, um einen aufgeladenen Leerenkern zu erschaffen. (3 Sek. Abklingzeit)\n\"Der Beschreibung nach sieht dies aus wie der Leerenkern, den Wirdal benötigt, doch scheint er komplett inaktiv zu sein. Es muss eine Möglichkeit geben, ihn aufzuladen...\"" }
entries[216636] = { ["name"] = "Aufgeladener Leerenkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Dieses Objekt scheint alles Licht und sämtliche Wärme in der Umgebung aufzusaugen und ist dennoch eiskalt.\"" }
entries[216637] = { ["name"] = "Ein Haufen gemischter Teile", ["text"] = "\"Es gibt sicher irgendjemanden irgendwo, der damit etwas anfangen könnte, aber für Euch sieht es nur nach Schrott aus.\"" }
entries[216645] = { ["name"] = "Partikel der Dunkelheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Dunkle Energie durchfließt dieses winzige, schwebende Energiepartikel. Welch unglaubliche Magie man damit wohl wirken könnte?\"" }
entries[216646] = { ["name"] = "Ziris Überraschungskiste", ["text"] = "Wird beim Aufheben gebunden\n\"Irgendwer wird den Inhalt sicher nützlich finden... vermutlich.\"\n<Zum Öffnen rechtsklicken>" }
