entries[216707] = { ["name"] = "Seidenmanschetten des Rottenmeisters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nHandgelenke Stoff\n31 Rüstung\n+6 Ausdauer\n+3 Intelligenz\nHaltbarkeit 30 / 30\nKlassen: Priester , Magier , Hexenmeister\nBenötigt Stufe 40\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 8." }
entries[216738] = { ["name"] = "Handbuch des Umleitens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nEntfernt all Eure bestehenden Combopunkte von Eurem Ziel und speichert sie bis zu 15 Sek. lang. Diese gespeicherten Combopunkte werden auf das nächste gegnerische Nichtspieler-Ziel übertragen, das Ihr mit einer Nahkampf- oder Distanzfähigkeit trefft.\n\"Lehrt Euch 'Umleiten'.\"" }
entries[216740] = { ["name"] = "Foliant der erweiterten Intelligenz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nSenkt die Manakosten von 'Arkane Intelligenz' um 50% und verlängert dessen Dauer um 50%.\n\"Lehrt Euch 'Erweiterte Intelligenz'.\"" }
entries[216744] = { ["name"] = "Schriftrolle der erhöhten Seelenstärke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nSenkt die Manakosten von 'Machtwort: Seelenstärke' um 50% und verlängert dessen Dauer um 50%.\n\"Lehrt Euch 'Erhöhte Seelenstärke'.\"" }
entries[216745] = { ["name"] = "Schriftrolle des Schattengeistes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nErschafft einen schattenhaften Geist, der das Ziel angreift. Der Zaubernde erhält bei einem Angriff des Schattengeists 5% Mana. Hält 15 Sek. lang an.\n\"Lehrt Euch 'Schattengeist'.\"" }
entries[216746] = { ["name"] = "Handbuch des Befehlsrufs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nDer Krieger schreit, wodurch sich die Ausdauer aller Gruppenmitglieder innerhalb von 30 Metern um 2 erhöht. Hält 5 Min. lang an.\n\"Lehrt Euch 'Befehlsruf'.\"" }
entries[216747] = { ["name"] = "Zauberfoliant der Seelenernte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nImmer wenn 'Seelendieb' Schaden verursacht, habt Ihr eine Chance, einen zusätzlichen Seelensplitter zu erhalten. Diese Chance steigt jedes Mal, wenn Ihr keinen Seelensplitter erhaltet.\n\"Lehrt Euch 'Seelenernte'.\"" }
entries[216748] = { ["name"] = "Zauberfoliant des Portals der Beschwörung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBeginnt ein Ritual, das ein Beschwörungsportal erstellt, welches von zwei Gruppen- oder Schlachtzugsmitgliedern benutzt werden kann, um ein ausgewähltes Gruppen- oder Schlachtzugsmitglied zu beschwören. Um das Ritual zu vervollständigen, werden der Zaubernde und zwei zusätzliche Gruppen- oder Schlachtzugsmitglieder benötigt. Um teilzunehmen, müssen sich alle Spielercharaktere außerhalb eines Kampfes befinden, auf das Portal rechtsklicken und dürfen sich nicht bewegen, bis das Ritual abgeschlossen ist.\n\"Lehrt Euch 'Portal der Beschwörung'.\"" }
entries[216764] = { ["name"] = "Handzettel der tiefen Wildnis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nSenkt die Manakosten von 'Mal der Wildnis' um 50% und verlängert dessen Dauer um 50%.\n\"Lehrt Euch 'Tiefe Wildnis'.\"" }
entries[216767] = { ["name"] = "Handzettel der Wiederbelebung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBringt einen toten Spielercharakter mit 15% Gesundheit und Mana wieder ins Leben zurück. Kann nicht im Kampf verwendet werden.\n\"Lehrt Euch 'Wiederbelebung'.\"" }
entries[216768] = { ["name"] = "Bekenntnis der verbesserten Segen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nErhöht die Dauer Eurer Zauber 'Segen der Macht', 'Segen der Weisheit', 'Segen der Rettung', 'Segen des Refugiums', 'Segen des Lichts' und 'Segen der Könige' um 100% und verringert ihre Manakosten um 50%.\n\"Lehrt Euch 'Verbesserte Segen'.\"" }
entries[216769] = { ["name"] = "Offenbarung der totemischen Projektion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nBewegt Eure aktiven Totems an die angegebene Position.\n\"Lehrt Euch 'Totemische Projektion'.\"" }
entries[216770] = { ["name"] = "Abhandlung zum Aspekt der Viper", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nDer Jäger nimmt die Aspekte einer Viper an. Jeder Eurer automatischen Distanz- und Nahkampfangriffe regeneriert Mana, der gesamte verursachte Schaden wird jedoch um 10% verringert. Zusätzlich erhaltet Ihr alle 3 Sek. 10% Eures maximalen Manas. Das gewonnene Mana basiert auf dem Tempo Eurer Waffe. Es kann immer nur jeweils ein Aspekt aktiv sein.\n\"Lehrt Euch 'Aspekt der Viper'.\"" }
entries[216771] = { ["name"] = "Handzettel der verbesserten Wiederherstellung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nEure Zauber 'Verjüngung' und 'Nachwachsen' können auf Zielen aktiv sein, die von 'Verjüngung' oder 'Nachwachsen' eines anderen Druiden betroffen sind.\n\"Lehrt Euch 'Verbesserte Wiederherstellung'.\"" }
entries[216879] = { ["name"] = "Mysteriöse Trollschriftrolle", ["text"] = "Einzigartig\nKlassen: Magier\nBenutzen: Entziffert die Schriftrolle mit einem Verständnisamulett. Wer weiß, welche Magie sie enthält." }
entries[216880] = { ["name"] = "Entzifferte Trollschriftrolle", ["text"] = "Einzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Priester" }
entries[216884] = { ["name"] = "Blutdurstklinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: (Unbekannt #636) (0)\nZweihändig Schwert\n649 - 764 Schaden Tempo 4.20\n(168.21 Schaden pro Sekunde)\n+333 Stärke\nHaltbarkeit 120 / 120\nBenötigt Stufe 125\nTrefferchance: Die versprochene Seele holen." }
entries[216914] = { ["name"] = "Befleckte Belobigung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 30\n\"Sie hat ihren Glanz verloren...\"" }
entries[216918] = { ["name"] = "Teufelsherzstiefel", ["text"] = "Wird beim Aufheben gebunden\nFüße Stoff\n150 Rüstung\n+25 Ausdauer\n+5 Intelligenz\n+5 Feuerwiderstand\nHaltbarkeit 50 / 50\nKlassen: Hexenmeister\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\nAnlegen: Verteidigung +10.\n\nSündhaftes Teufelsherz (0/8)\nTeufelsherzbindungen\nTeufelsherzstiefel\nTeufelsherzkrone\nTeufelsherzumarmung\nTeufelsherzhandschutz\nTeufelsherzgamaschen\nTeufelsherzmantel\nTeufelsherzschärpe\n(2) Set : 'Verbannen' ist ein Spontanzauber und kann auf Euch selbst gewirkt werden, während Ihr ein Dämon seid. Ihr könnt 'Verbannen' nicht auf Euch selbst wirken, solange 'Vorahnung' auf Euch wirkt, und 'Verbannen' belegt Euch 1 Min. lang mit 'Vorahnung'.\n(4) Set : Jedes Mal, wenn Ihr Schaden erleidet, erhaltet Ihr und Euer Diener Mana in Höhe des erlittenen Schadens, bis zu maximal 420 Mana pro Ereignis. Kann nur einmal alle paar Sekunden auftreten. (3.5s Abklingzeit)\n(6) Set : Eure Treffer mit 'Schattenspalten' haben eine Chance von 20%, Euch einen Seelensplitter zu gewähren, die Abklingzeit von 'Seelenfeuer' abzuschließen und Euren nächsten Einsatz von 'Seelenfeuer' innerhalb von 10 Sek. zu einem Spontanzauber zu machen. (Procchance: 20%, 100ms Abklingzeit)" }
entries[216919] = { ["name"] = "Teufelsherzschärpe", ["text"] = "Wird beim Aufheben gebunden\nTaille Stoff\n137 Rüstung\n+25 Ausdauer\n+5 Intelligenz\n+7 Feuerwiderstand\nHaltbarkeit 35 / 35\nKlassen: Hexenmeister\nBenötigt Stufe 60\nAnlegen: Verteidigung +6.\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 9.\n\nSündhaftes Teufelsherz (0/8)\nTeufelsherzbindungen\nTeufelsherzstiefel\nTeufelsherzkrone\nTeufelsherzumarmung\nTeufelsherzhandschutz\nTeufelsherzgamaschen\nTeufelsherzmantel\nTeufelsherzschärpe\n(2) Set : 'Verbannen' ist ein Spontanzauber und kann auf Euch selbst gewirkt werden, während Ihr ein Dämon seid. Ihr könnt 'Verbannen' nicht auf Euch selbst wirken, solange 'Vorahnung' auf Euch wirkt, und 'Verbannen' belegt Euch 1 Min. lang mit 'Vorahnung'.\n(4) Set : Jedes Mal, wenn Ihr Schaden erleidet, erhaltet Ihr und Euer Diener Mana in Höhe des erlittenen Schadens, bis zu maximal 420 Mana pro Ereignis. Kann nur einmal alle paar Sekunden auftreten. (3.5s Abklingzeit)\n(6) Set : Eure Treffer mit 'Schattenspalten' haben eine Chance von 20%, Euch einen Seelensplitter zu gewähren, die Abklingzeit von 'Seelenfeuer' abzuschließen und Euren nächsten Einsatz von 'Seelenfeuer' innerhalb von 10 Sek. zu einem Spontanzauber zu machen. (Procchance: 20%, 100ms Abklingzeit)" }
