entries[217736] = { ["name"] = "Rune des Zirkels", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Euren Helm mit der Rune 'Ehre unter Dieben':\n\nErzielt ein Spielercharakter in Eurer Gruppe mit einem Zauber oder einer Fähigkeit einen kritischen Treffer, gewinnt Ihr einen zusätzlichen Combopunkt auf Eurem aktuellen Ziel dazu. Dieser Effekt kann nur einmal pro Sekunde auftreten.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
