entries[219223] = { ["name"] = "Zorn des Klingenmeisters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n104 - 157 Schaden Tempo 3.00\n(43.50 Schaden pro Sekunde)\n+17 Stärke\n+10 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 50\nBenutzen: Greift bis zu 4 Gegner innerhalb von 8 Metern an, fügt jedem Gegner Waffenschaden zu und setzt die Abklingzeit Eurer Fähigkeit 'Wirbelwind' zurück. (2 Min Abklingzeit)" }
