entries[220164] = { ["name"] = "Rune des Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Stiefel mit der Rune 'Gladiatorhaltung':\n\nEine aggressive Haltung, die beim Tragen eines Schildes den Schaden um 10% und die Blockchance um 10% erhöht, dabei jedoch die Rüstung um 30% und die erzeugte Bedrohung um 30% verringert. Zusätzlich erhaltet Ihr 50% mehr Wut, wenn Eure Nahkampfangriffe einem Gegner Schaden zufügen, der Euch nicht als Ziel hat.\n\nWährend Ihr in der 'Gladiatorhaltung' einen Schild tragt, könnt Ihr sämtliche Fähigkeiten einsetzen, die auf andere Haltungen beschränkt sind.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[220165] = { ["name"] = "Rune des Zorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euren Helm mit der Rune 'Zorn':\n\nDer Schaden Eurer 'Weihe' kann nun kritisch treffen, und der Schaden Eurer Zauber 'Exorzismus', 'Heiliger Schock', 'Sonnenlicht', 'Heiliger Zorn' und 'Weihe' erhält eine zusätzliche Chance auf kritische Treffer, die der kritischen Trefferchance Eurer Nahkampftreffer entspricht.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[220166] = { ["name"] = "Feuriger Höllenbestienkern", ["text"] = "Questgegenstand" }
entries[220167] = { ["name"] = "Schimmernder Grabstaub", ["text"] = "Questgegenstand\n\"Grabstaub von der Ruhestätte eines Mordopfers einer geliebten Person...\"" }
entries[220168] = { ["name"] = "Dreifach gebrautes Schmelzlagerbier", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Elixier des Feuers, erschaffen mit ruhigen Händen und einem unruhigen Gemüt...\"" }
entries[220169] = { ["name"] = "Symbol des Glaubens", ["text"] = "Questgegenstand\n\"Ein Symbol des Glaubens, ein Geschenk von jemandem mit neu entdeckter Bestimmung...\"" }
entries[220170] = { ["name"] = "Notiz von Gregory", ["text"] = "Wird beim Aufheben gebunden\n<Zum Lesen rechtsklicken>" }
entries[220173] = { ["name"] = "Parasomnie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nZweihändig Schwert\n142 - 213 Schaden Tempo 3.40\n(52.21 Schaden pro Sekunde)\n+15 Stärke\n+11 Beweglichkeit\n+28 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Krieger , Paladin\nBenötigt Stufe 50\nTrefferchance: Belegt das Ziel mit 'Parasomnie', wodurch es bis zu 2 Sek. lang ziellos umherwandert.\n\"Ausgeburt des Alptraums\"" }
entries[220213] = { ["name"] = "Teuflisches Lebensblut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[220214] = { ["name"] = "Höllischer Kettenverbund", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)" }
entries[220216] = { ["name"] = "Höllenlasso", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Schwächt Calefactus den Entfesselten. (30 Sek. Abklingzeit)" }
entries[220217] = { ["name"] = "Rune des Gefräßigen", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nPrägt Euren Helm mit der Rune 'Schneller Tod':\n\nVerringert die Abklingzeit von 'Schnellfeuer' um 80%, 'Schnellfeuer' erhöht zusätzlich das Nahkampfangriffstempo um 40% und Eure nächste Schussfähigkeit innerhalb von 20 Sek., nachdem Ihr einen Gegner getötet habt, der Erfahrung oder Ehre gewährt, verursacht 20% mehr Schaden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[220345] = { ["name"] = "Blutige Zauberei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Beschreibt eine Vielzahl von mächtigen Blutritualen. Eine kontroverse Erweiterung für die Sammlung jeder Bücherei.\"" }
entries[220346] = { ["name"] = "Legenden der Gezeitenweisen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Vollgekritzelt mit kaum leserlichen Notizen und Diagrammen, die von unruhiger Hand stammen. Könnte trotzdem eine nette Erweiterung für die Sammlung jeder Bücherei bedeuten.\"" }
entries[220347] = { ["name"] = "Die Schwelle und das Arkane", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Die Wörter auf der Seite verschwimmen und lassen nicht zu, gelesen zu werden. Eine rätselhafte Erweiterung für die Sammlung jeder Bücherei.\"" }
entries[220348] = { ["name"] = "Alltägliche Etikette", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine Abhandlung zur Rolle von Elementarmagie in der feinen Gesellschaft der Hochgeborenen. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\"" }
entries[220349] = { ["name"] = "Steinwerkentwürfe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Architektonische Techniken zum Bau von stabilen Gebäuden, die selbst die schlimmsten Katastrophen überstehen. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\"" }
entries[220350] = { ["name"] = "Giftige Reisen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Notizen zu bewusstseinsverändernden Eigenschaften verschiedener Toxine und Gifte. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\"" }
entries[220351] = { ["name"] = "Düsteres Luftsapta", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ermöglicht dem Schamanen, Elementargeister zu sehen." }
entries[220352] = { ["name"] = "Möglichkeiten des Metalls", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Zwergentechniken für die Anwendung von Magie in der Metallurgie, beim Ressourcenabbau und in der Schwerindustrie. Eine informative, wenn auch eher fade Erweiterung für die Sammlung jeder Bücherei.\"" }
entries[220353] = { ["name"] = "Beschwörerkodex", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine Ansammlung von Zaubern und Arkantheorien, die aus der Zeit vor dem Krieg stammen und schon lange nicht mehr angewendet werden. Eine schöne Erweiterung für die Sammlung jeder Bücherei.\"" }
entries[220360] = { ["name"] = "Rune des Erblühens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Armschienen mit der Rune 'Erblühen':\n\nEure 'Rasche Heilung' löst nun auch 'Erblühen' aus und heilt alle Mitglieder der Gruppe innerhalb von 15 Metern um den Zielort von 'Rasche Heilung' 15 Sek. lang alle 1 Sek um [Quellwert] Gesundheit.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[220375] = { ["name"] = "Fragment der Luft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert das Fragment der Luft mit Elementaressenzen. Kann dabei helfen, den verderbten Schrein zu finden." }
entries[220379] = { ["name"] = "Zerrissene Notizen des Schamanen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Schamane\n\"Hastig geschriebene, fast unleserliche Notizen. Die Seiten scheinen um etwas anderes gewickelt zu sein.\"" }
entries[220446] = { ["name"] = "Überirdischer Schatz", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[220510] = { ["name"] = "Elementaressenz", ["text"] = "Questgegenstand\nKlassen: Schamane" }
entries[220511] = { ["name"] = "Großhelm des Alptraums", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n469 Rüstung\n+25 Stärke\n+6 Ausdauer\nHaltbarkeit 80 / 80\nBenötigt Stufe 50\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%." }
entries[220512] = { ["name"] = "Makelloser Goldstahlhelm", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n469 Rüstung\n+8 Ausdauer\n+14 Intelligenz\nHaltbarkeit 80 / 80\nBenötigt Stufe 50\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 44.\nAnlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her." }
entries[220514] = { ["name"] = "Visier der tiefgrünen Federn", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n266 Rüstung\n+14 Intelligenz\n+13 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Stufe 50\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 31.\nAnlegen: Stellt alle 5 Sek. 8 Punkt(e) Mana wieder her." }
entries[220515] = { ["name"] = "Verzauberter Smaragdhelm", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n266 Rüstung\n+9 Ausdauer\n+8 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Stufe 50\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 29." }
entries[220516] = { ["name"] = "Schlitzers vergessenes Visier", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n266 Rüstung\n+12 Ausdauer\n+12 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Stufe 50\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: +30 Angriffskraft." }
entries[220518] = { ["name"] = "Ba'hams verstaubter Hut", ["text"] = "Wird beim Aufheben gebunden\nKopf Leder\n128 Rüstung\n+15 Ausdauer\nHaltbarkeit 60 / 60\nBenötigt Stufe 50\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer zu erzielen, um 1%.\nAnlegen: +38 Angriffskraft." }
