entries[220588] = { ["name"] = "Kobragiftzahnklaue", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Faustwaffe\n73 - 136 Schaden Tempo 2.60\n(40.19 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nBenötigt Stufe 50\nTrefferchance: Gewährt Euch einen zusätzlichen Angriff bei Eurem nächsten Schwung.\n\nAufstieg der Schlange (0/2)\nKobragiftzahnklaue\nSchlangenschläger\n(2) Set : Gewährt dem Benutzer beim Verursachen von Distanz- oder Nahkampfschaden eine kleine Chance, mit dem Segen der Schlange erfüllt zu werden. Distanz- und Nahkampfangriffskraft 12 Sek. lang um 150 erhöht. (Procchance: 3%, 2Min. Abklingzeit)" }
entries[220589] = { ["name"] = "Schlangenschläger", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Faustwaffe\n42 - 78 Schaden Tempo 1.50\n(40.00 Schaden pro Sekunde)\n+9 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 50\nTrefferchance: Vergiftet den Gegner und verursacht 50 Naturschaden, verringert den Naturwiderstand um 60 und erhöht sämtlichen erlittenen Heilig- und Naturschaden 20 Sek. lang um 8%. Wirkt nur bei Gegnern der Stufe 55 oder niedriger.\n\nAufstieg der Schlange (0/2)\nKobragiftzahnklaue\nSchlangenschläger\n(2) Set : Gewährt dem Benutzer beim Verursachen von Distanz- oder Nahkampfschaden eine kleine Chance, mit dem Segen der Schlange erfüllt zu werden. Distanz- und Nahkampfangriffskraft 12 Sek. lang um 150 erhöht. (Procchance: 3%, 2Min. Abklingzeit)" }
