entries[220607] = { ["name"] = "Totem der gequälten Ahnen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nBenötigt Stufe 50\nAnlegen: 'Flammenschock' erhöht 12 Sek. lang Angriffskraft, Zauberschaden und Heilung um 10." }
