entries[220609] = { ["name"] = "Tuch der Dämmerung", ["text"] = "Wird beim Aufheben gebunden\nRücken\n39 Rüstung\n+8 Beweglichkeit\n+14 Ausdauer\nBenötigt Stufe 50" }
entries[220610] = { ["name"] = "Rune der geistigen Gewandtheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Euren Helm mit der Rune 'Geistige Gewandtheit':\n\nSchaden mit 'Sturmschlag' zu verursachen, erhöht 30 Sek. lang Eure Angriffskraft um 150% Eurer Intelligenz und Euren Zauberschaden um 35% Eurer gesamten Angriffskraft.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[220611] = { ["name"] = "Hukkus Hexerumhang", ["text"] = "Wird beim Aufheben gebunden\nRücken\n39 Rüstung\n+10 Intelligenz\nBenötigt Stufe 50\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 15." }
entries[220612] = { ["name"] = "Rune der Flutwellen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Euren Helm mit der Rune 'Flutwellen':\n\nWenn Ihr 'Kettenheilung' oder 'Springflut' wirkt, gewinnt Ihr 2 Aufladungen von 'Flutwelle' hinzu, was die Zauberzeit Eurer 'Welle der Heilung' um 30% und die Zauberzeit Eurer 'Kettenheilung' um 15% verringert und die kritische Trefferchance Eures Zaubers 'Geringe Welle der Heilung' um 25% erhöht.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[220613] = { ["name"] = "Rune des rollenden Donners", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Eure Armschienen mit der Rune 'Rollender Donner':\n\n'Blitzschlag' und 'Kettenblitzschlag' haben eine Chance von 50%, Eurem aktiven 'Blitzschlagschild' eine zusätzliche Aufladung zu gewähren, bis zu 9 Aufladungen.\n\n'Erdschock' entfesselt nun alle Aufladungen von 'Blitzschlagschild' über 3, was dem Ziel ihren Schaden zufügt und Euch pro Aufladung Energie in Höhe von 2% Eures maximalen Manas gewährt.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[220614] = { ["name"] = "Rune des statischen Schocks", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Eure Armschienen mit der Rune 'Statischer Schock':\n\nEuer 'Blitzschlagschild' hat jetzt 9 Aufladungen und Eure Nahkampfangriffe haben eine Chance von 12% (beim Kämpfen mit zwei Waffen eine Chance von 6% ), eine dieser Aufladungen auszulösen und Eurem Ziel sofort Schaden zuzufügen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[220615] = { ["name"] = "Pantherfellumhang", ["text"] = "Wird beim Aufheben gebunden\nRücken\n39 Rüstung\n+6 Stärke\n+15 Beweglichkeit\nBenötigt Stufe 50" }
entries[220616] = { ["name"] = "Rune der Überladung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Eure Armschienen mit der Rune 'Überladen':\n\nEuer 'Blitzschlagschild' verliert nie seine Aufladungen, hat jetzt eine Abklingzeit von 3 Sek. und fügt allen Gegnern innerhalb von 8 Metern Schaden zu.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[220617] = { ["name"] = "Rune der Pandemie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euren Helm mit der Rune 'Pandemie':\n\nRegelmäßiger Schaden durch Eure Fähigkeiten 'Verderbnis', 'Instabiles Gebrechen', 'Fluch der Pein', 'Feuerbrand', 'Fluch der Verdammnis' und 'Lebensentzug' kann jetzt kritisch treffen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[220618] = { ["name"] = "Rune der Feuerbrandaura", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Armschienen mit der Rune 'Feuerbrandaura':\n\nImmer wenn ein Gegner Euch im Nahkampf angreift, werden Gegner in der Nähe verbrannt und erleiden [Quellwert] Schaden. Kann nicht häufiger als einmal pro Sekunde auftreten. Verringert außerdem sämtlichen erlittenen Magieschaden um 10% und erhöht den verursachten Feuerschaden um 10%. Hält bis Abbruch lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[220619] = { ["name"] = "Blutzeremonie der Atal'ai", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Ein Opferdolch, auf dem der Gesang einer uralten Blutzeremonie der Atal'ai eingraviert ist. (35 Sek. Abklingzeit)\n\"Der Blutloa wählt nur Würdige aus.\"" }
entries[220620] = { ["name"] = "Schädel der Windnatter", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Mit Rechtsklick Eure Windnatter beschwören oder wieder freigeben." }
