entries[220632] = { ["name"] = "Blutritualmedaillon der Atal'ai", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\nBenutzen: Erhöht 20 Sek. lang Euren Nahkampf- und Distanzschadensbonus um 20 Punkte. Jedes Mal, wenn Ihr ein Ziel trefft, wird dieser Bonus um 1 verringert. (2 Min Abklingzeit)" }
entries[220633] = { ["name"] = "Blutritualabzeichen der Atal'ai", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\nBenutzen: Erhöht Eure Rüstung 20 Sek. lang um 1.000 und Eure Verteidigungsfertigkeit um 20. Jedes Mal, wenn Euch Nahkampf- oder Distanzschaden zugefügt wird, wird dieser Bonus um 100 Rüstung und 2 Verteidigung verringert. (2 Min Abklingzeit)" }
entries[220634] = { ["name"] = "Blutritualamulett der Atal'ai", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\nBenutzen: Erhöht 20 Sek. lang Euren Zauberschaden um bis zu 96 Schaden und Eure Heilung um bis zu 192 Gesundheit. Bei jedem Einsatz eines Zaubers wird der Bonus um 8 Zauberschaden und 16 Heilung verringert. (2 Min Abklingzeit)" }
entries[220635] = { ["name"] = "Atal'alarions verzauberter Fels", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Fokussiert Euren Geist auf Atal'alarions Lieblingsfelsen, verzaubert mit den letzten Echos seiner Seele. (15 Min Abklingzeit)" }
