entries[220642] = { ["name"] = "Plattenrüstung des verbannten Märtyrers", ["text"] = "Wird beim Aufheben gebunden\nBrust Platte\n577 Rüstung\n+5 Stärke\n+9 Beweglichkeit\n+18 Ausdauer\nHaltbarkeit 135 / 135\nKlassen: Krieger , Paladin\nBenötigt Stufe 50\nAnlegen: Erhöht den Blockwert Eures Schildes um 24.\n\nVollplattierung des verbannten Märtyrers (0/3)\nPlattenrüstung des verbannten Märtyrers\nPlattenbeinschützer des verbannten Märtyrers\nPlattenstiefel des verbannten Märtyrers\n(2) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n(3) Set : Erhaltet 6 Sek. lang einen Blockwert von 50 nach dem Blocken." }
entries[220643] = { ["name"] = "Plattenbeinschützer des verbannten Märtyrers", ["text"] = "Wird beim Aufheben gebunden\nBeine Platte\n505 Rüstung\n+11 Stärke\n+18 Ausdauer\nHaltbarkeit 100 / 100\nKlassen: Krieger , Paladin\nBenötigt Stufe 50\nAnlegen: Erhöht den Blockwert Eures Schildes um 23.\n\nVollplattierung des verbannten Märtyrers (0/3)\nPlattenrüstung des verbannten Märtyrers\nPlattenbeinschützer des verbannten Märtyrers\nPlattenstiefel des verbannten Märtyrers\n(2) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n(3) Set : Erhaltet 6 Sek. lang einen Blockwert von 50 nach dem Blocken." }
entries[220648] = { ["name"] = "Plattenstiefel des verbannten Märtyrers", ["text"] = "Wird beim Aufheben gebunden\nFüße Platte\n397 Rüstung\n+7 Stärke\n+19 Ausdauer\nHaltbarkeit 65 / 65\nKlassen: Krieger , Paladin\nBenötigt Stufe 50\nAnlegen: Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 1%.\n\nVollplattierung des verbannten Märtyrers (0/3)\nPlattenrüstung des verbannten Märtyrers\nPlattenbeinschützer des verbannten Märtyrers\nPlattenstiefel des verbannten Märtyrers\n(2) Set : Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n(3) Set : Erhaltet 6 Sek. lang einen Blockwert von 50 nach dem Blocken." }
