entries[220913] = { ["name"] = "Rune der Sprengung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Armschienen mit der Rune 'Abrisskommando':\n\nEure kritischen Nahkampftreffer machen Euch wütend (und aktivieren Fähigkeiten, für die Ihr wütend sein müsst) und erhöhen den Schaden von 'Tödlicher Stoß', 'Blutdurst' und 'Schildschlag' 12 Sek. lang um 10%.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
