entries[221020] = { ["name"] = "Rune der Mondgöttin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Armschienen mit der Rune 'Feuer Elunes':\n\nEinige Eurer Zauber und Fähigkeiten verlängern die Dauer Eurer regelmäßigen Schadens- und Heileffekte auf ihrem Ziel:\n\n'Sternenfeuer' verlängert 'Mondfeuer' um 6 Sek.\n'Zorn' verlängert 'Sonnenfeuer' um 3 Sek.\n'Nachwachsen' verlängert 'Verjüngung' um 6 Sek.\n'Schreddern' verlängert 'Zerfetzen' um 2 Sek.\n\nJeder Effekt kann nur bis zur ursprünglichen Dauer verlängert werden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221021] = { ["name"] = "Alptraumsaat" }
entries[221024] = { ["name"] = "Fläschchen der unvergänglichen Alpträume", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenötigt Alchimie (250)\nBenutzen: Erhöht die Distanz- und Nahkampfangriffskraft um 45. Die Vorteile dieses Fläschchens wirken nur in Gebieten, die unter dem Einfluss des Alptraums stehen. (30 Sek. Abklingzeit)\n\"Die Flasche scheint nie leer zu werden, egal, wie viel man davon trinkt.\"" }
entries[221025] = { ["name"] = "Leerenaufgeladene Unterarmschienen des Herbeirufers", ["text"] = "Wird beim Aufheben gebunden\nHandgelenke Stoff\n37 Rüstung\n+7 Ausdauer\n+8 Intelligenz\nHaltbarkeit 35 / 35\nBenötigt Stufe 50\nBenötigt Ingenieurskunst (250)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nAnlegen: Schützt gegen bestimmte Arten von psychischen Angriffen.\nBenutzen: Kanalisiert die Macht der Leere und verleiht 15 Sek. lang Immunität gegenüber Furcht. (10 Min Abklingzeit)\n\"Die besten Ideen aus Ziris ursprünglichen Entwurf mit ein paar zusätzlichen Modifikationen.\"" }
entries[221026] = { ["name"] = "Leerenaufgeladene Unterarmschienen des Rächers", ["text"] = "Wird beim Aufheben gebunden\nHandgelenke Leder\n75 Rüstung\n+9 Stärke\n+18 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 40 / 40\nBenötigt Stufe 50\nBenötigt Ingenieurskunst (250)\nAnlegen: Schützt gegen bestimmte Arten von psychischen Angriffen.\nBenutzen: Kanalisiert die Macht der Leere und verleiht 15 Sek. lang Immunität gegenüber Furcht. (10 Min Abklingzeit)\n\"Die besten Ideen aus Ziris ursprünglichen Entwurf mit ein paar zusätzlichen Modifikationen.\"" }
entries[221027] = { ["name"] = "Leerenaufgeladene Unterarmschienen des Beschützers", ["text"] = "Wird beim Aufheben gebunden\nHandgelenke Platte\n275 Rüstung\n+10 Stärke\n+12 Ausdauer\nHaltbarkeit 55 / 55\nBenötigt Stufe 50\nBenötigt Ingenieurskunst (250)\nAnlegen: Erhöht den Blockwert Eures Schildes um 19.\nAnlegen: Schützt gegen bestimmte Arten von psychischen Angriffen.\nBenutzen: Kanalisiert die Macht der Leere und verleiht 15 Sek. lang Immunität gegenüber Furcht. (10 Min Abklingzeit)\n\"Die besten Ideen aus Ziris ursprünglichen Entwurf mit ein paar zusätzlichen Modifikationen.\"" }
entries[221028] = { ["name"] = "Verzaubertes Siegel: Lebendige Träume", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 50\nBenötigt Verzauberkunst (250)\nBenutzen: Erhaltet ein verzaubertes Siegel der lebendigen Träume, das Euch ermächtigt, wodurch 30 Min. lang der verursachte Schaden und die hervorgerufene Heilung Eurer Zauber um bis zu 30 und Eure Angriffskraft um 30 erhöht wird. Dieser Effekt kann nur außerhalb des Kampfes angewandt werden. (30 Min Abklingzeit)" }
entries[221030] = { ["name"] = "Atal'aimojo der verbotenen Magie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (2)\nBenötigt Stufe 50\nBenutzen: Erhöht die Zaubermacht um 40. Erfolgreiche Zaubertreffer haben eine Chance, einen Schattenblitz auf das Ziel zu entfesseln. Es kann immer nur ein Trank der Atal'ai zur selben Zeit aktiv sein. Dies hat außerhalb des Versunkenen Tempels keinen Effekt. (Procchance: 25%, 40s Abklingzeit) (3 Sek. Abklingzeit)\n\"Die flackernden Schatten in diesem verzauberten Wasser, umgewandelt aus der Essenz des Atal'aimojos, verschleiern, was sich darin befindet...\"" }
entries[221191] = { ["name"] = "Traumstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[221192] = { ["name"] = "Traumtagebuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Lesen rechtsklicken>" }
entries[221193] = { ["name"] = "Smaragdring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+12 Ausdauer\n+5 Arkanwiderstand\nBenötigt Stufe 45\nBenötigtSmaragdwärter\n- Wohlwollend\nAnlegen: +14 Angriffskraft.\nBenutzen: Begebt Euch in den Traum eines anvisierten Verbündeten. (1 Stunde Abklingzeit)\n\"Im Inneren des prachtvollen Smaragds pulsiert ein Licht.\"" }
entries[221196] = { ["name"] = "Atal'aimojo des Krieges", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (2)\nBenötigt Stufe 50\nBenutzen: Erhöht die Nahkampf- und Distanzangriffskraft um 48. Bei Nahkampf- und Distanzangriffen besteht eine Chance, größer zu werden, wodurch 10 Sek. lang die Stärke oder Beweglichkeit um 35 erhöht wird (je nach dem, welcher Wert höher ist). Es kann immer nur ein Trank der Atal'ai zur selben Zeit aktiv sein. Dies hat außerhalb des Versunkenen Tempels keinen Effekt. (Procchance: 15%, 40s Abklingzeit) (3 Sek. Abklingzeit)\n\"Ihr wollt in die Schlacht ziehen, als Ihr den reizenden roten Schein des Tranks erblickt...\"" }
entries[221199] = { ["name"] = "Satyrkrauttinktur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Heilt eine Kreatur von Satyrverderbnis." }
entries[221256] = { ["name"] = "Rechter Arm des Vernichters", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert ein Stück mit 4 anderen, um Iodac wiederaufzubauen." }
entries[221257] = { ["name"] = "Linker Arm des Vernichters", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert ein Stück mit 4 anderen, um Iodac wiederaufzubauen." }
entries[221258] = { ["name"] = "Rechter Fuß des Vernichters", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert ein Stück mit 4 anderen, um Iodac wiederaufzubauen." }
