entries[221260] = { ["name"] = "Kopf des Vernichters", ["text"] = "Wird beim Aufheben gebunden" }
entries[221261] = { ["name"] = "Wildgeflüstergebräu", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört den Geist von Agamaggan. Kann nur oben auf der Wendel der Dornen in den Hügeln von Razorfen verwendet werden, nachdem alle Gegner in der Nähe besiegt wurden. (5 Sek. Abklingzeit)" }
entries[221262] = { ["name"] = "Wilde Opfergabe", ["text"] = "Wird beim Aufheben gebunden" }
entries[221267] = { ["name"] = "Rune des Blutdurstigen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euren Helm mit der Rune 'Verlangen nach Blut':\n\nImmer wenn Eure Fähigkeit 'Verwunden' Schaden verursacht, wird Eure Fähigkeit 'Überwältigen' 9 Sek. lang oder für 1 Angriff aktiviert. Dieser Effekt tritt alle 6 Sek. höchstens einmal ein.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
