entries[221307] = { ["name"] = "Dunkelmond-Karte: Verfall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\nAnlegen: Zauber und Angriffe entziehen dem Ziel manchmal 40 Gesundheit und belegen es mit einem Stapel 'Verfall'. Bei 5 Stapeln von 'Verfall' erleidet das Ziel 225 bis 375 Schaden. (3s Abklingzeit)" }
entries[221308] = { ["name"] = "Dunkelmond-Karte: Wildes Wachstum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\nAnlegen: Bei Euren direkten Heilzaubern und effektiven Ticks Eurer regelmäßiger Heilung besteht eine Chance, beim Ziel 8 Energie, 1% Mana oder 4 Wut wiederherzustellen. (Procchance: 10%)" }
entries[221309] = { ["name"] = "Dunkelmond-Karte: Sandsturm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\nAnlegen: Chance, dass Zauber und Angriffe einen Sandsturm heraufbeschwören, der Euch umkreist und Zielen in seiner Bahn 50 bis 100 Naturschaden zufügt. (Procchance: 30%, 8s Abklingzeit)" }
entries[221310] = { ["name"] = "Dunkelmond-Karte: Qual", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\nAnlegen: Bei Angriffen und Zaubern des Trägers besteht eine Chance, das Ziel zu quälen und es 3 Sek. lang ziellos umherwandern zu lassen. (Procchance: 5%, 15s Abklingzeit)" }
entries[221311] = { ["name"] = "Atal'aimojo des Lebens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (2)\nBenötigt Stufe 50\nBenutzen: Erhöht die verursachte Heilung um 45, die Manaregeneration alle 5 Sek. um 11 und Eure Heilungen haben eine Chance, 8 Energie, 1% Mana oder 4 Wut wiederherzustellen. Es kann immer nur ein Trank der Atal'ai zur selben Zeit aktiv sein. Dies hat außerhalb des Versunkenen Tempels keinen Effekt. (Procchance: 25%, 20s Abklingzeit) (3 Sek. Abklingzeit)\n\"Ein tiefes Blau steigt aus dem Inhalt dieser Phiole hervor. Es fühlt sich fast so an, als wollte die Flüssigkeit, dass Ihr sie trinkt.\"" }
entries[221312] = { ["name"] = "Fläschchen mit Atal'aimojo", ["text"] = "\"Das beste Mojo der Atal'aitrolle\"" }
entries[221313] = { ["name"] = "Fläschchen des alptraumhaften Mojo", ["text"] = "\"Machtvolles alptraumerfülltes Voodoo der Atal'ai wirbelt in der Phiole herum.\"" }
entries[221314] = { ["name"] = "Steckbrief", ["text"] = "Questgegenstand\nEinzigartig\n\"Die grobe Skizze eines Dunkeleisenzwergs.\"\n<Zum Lesen rechtsklicken>" }
entries[221315] = { ["name"] = "Regenbogengenerator", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Regenbogenkraft! (30 Min Abklingzeit)" }
entries[221316] = { ["name"] = "Premos haltungswahrende Uniform", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nHemd\nBenutzen: Konzentriert Euch." }
entries[221317] = { ["name"] = "Feralas-Leykristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwendet 4 Leykristalle, um Euch auf Azeroth einzustimmen und eine neue Fähigkeit zu erlernen." }
entries[221318] = { ["name"] = "Azshara-Leykristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwendet 4 Leykristalle, um Euch auf Azeroth einzustimmen und eine neue Fähigkeit zu erlernen." }
entries[221319] = { ["name"] = "Blackrock-Leykristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwendet 4 Leykristalle, um Euch auf Azeroth einzustimmen und eine neue Fähigkeit zu erlernen." }
entries[221320] = { ["name"] = "Hinterland-Leykristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwendet 4 Leykristalle, um Euch auf Azeroth einzustimmen und eine neue Fähigkeit zu erlernen." }
entries[221321] = { ["name"] = "Atal'aisiegel der Macht", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Fügt einem Gegenstand für den Schulterplatz dauerhaft 15 Angriffskraft hinzu." }
entries[221322] = { ["name"] = "Atal'aisiegel des Mojo", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Fügt einem Gegenstand für den Schulterplatz dauerhaft eine um bis zu 9 erhöhte Schadens- und Heilwirkung durch Zauber und magische Effekte hinzu." }
entries[221323] = { ["name"] = "Atal'aisiegel der inneren Ruhe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Fügt einem Gegenstand für den Schulterplatz dauerhaft eine um bis zu 18 erhöhte Heilwirkung durch Zauber und magische Effekte hinzu." }
entries[221324] = { ["name"] = "Spröder Schlüssel zur Schattenschmiede", ["text"] = "Questgegenstand\nEinzigartig\nDauer: 15 min\n\"Es wäre unmöglich, diesen zerbröselnden Schlüssel Eurem Bund hinzuzufügen.\"" }
entries[221325] = { ["name"] = "Leichtplodier-Sprengsatz", ["text"] = "Wird beim Aufheben gebunden\nDauer: 15 min\nBenutzen: Sprengt schwere verschlossene Türen auf.\n\"Die langsam abfackelnde Zündschnur brennt bereits!\"" }
entries[221326] = { ["name"] = "Heiliges Hirschherz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bietet die Opfergabe am Schrein des Tieres dar." }
entries[221327] = { ["name"] = "Bauplan: Gnomenschrumpfstrahl", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGnomen-Schrumpfstrahl\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst (205)\nBenutzen: Lässt das Ziel schrumpfen und verringert seine Angriffskraft um 250. Zumindest ist das meistens der Fall... (5 Min Abklingzeit)\nBenötigt Mithrilrohr , Instabiler Auslöser , Mithrilbarren (4), Fläschchen Mojo (4), Jade (2)" }
entries[221328] = { ["name"] = "Bauplan: Gnomenschutzbrille", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGnomen-Schutzbrille\nWird beim Aufheben gebunden\nKopf Stoff\n45 Rüstung\n+9 Beweglichkeit\n+9 Ausdauer\n+9 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (210)\nBenötigt Feuerschutzbrille , Mithrilrohr , Goldkraftkern (2), Fläschchen Mojo (2), Schweres Leder (2)" }
entries[221329] = { ["name"] = "Bauplan: Gnomen-Net-o-Matik-Projektor", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGnomen-Net-o-Matik-Projektor\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst (210)\nBenutzen: Hält das Ziel 10 Sek. lang in einem Netz fest. Das Netz ist allerdings mit einer Menge Haken bestückt und verfängt sich manchmal auch in der Kleidung des Benutzers, wenn es abgefeuert wird... (10 Min Abklingzeit)\nBenötigt Mithrilrohr , Schattenseide (2), Dicke Spinnenseide (4), Robustes Sprengpulver (2), Mithrilbarren (4)" }
entries[221330] = { ["name"] = "Bauplan: Gnomenunglücksverhinderungsgürtel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGnomen-Unglücksverhinderungsgürtel\nWird beim Anlegen gebunden\nTaille Leder\n66 Rüstung\n+6 Ausdauer\nHaltbarkeit 30 / 30\nBenötigt Ingenieurskunst (215)\nBenutzen: Ein Kraftfeldschild beschützt Euch vor dem nächsten zugefügten 500-Schaden im Verlauf der nächsten 10 Min.. WARNUNG: Kraftfeld kann überladen werden, wenn es getroffen wird. Der Träger wird dann für gewisse Zeit aus dieser Dimension entfernt. (Procchance: 5%) (1 Stunde Abklingzeit)\nBenötigt Schwärzlicher Gürtel , Mithrilbarren (4), Echtsilberbarren (2), Instabiler Auslöser , Aquamarin (2)" }
entries[221331] = { ["name"] = "Bauplan: Gnomenraketenstiefel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGnomen-Raketenstiefel\nWird beim Anlegen gebunden\nFüße Stoff\n41 Rüstung\nHaltbarkeit 35 / 35\nBenötigt Ingenieurskunst (225)\nBenutzen: Diese Stiefel erhöhen Euer Lauftempo 20 Sek. lang erheblich. WARNUNG: Ihre Stromversorgung und Gyros funktionieren nicht immer so, wie sie eigentlich sollten. (30 Min Abklingzeit)\nBenötigt Schwarze Magiestoffstiefel , Mithrilrohr (2), Schweres Leder (4), Robustes Sprengpulver (8), Gyrochronatom (4)" }
entries[221332] = { ["name"] = "Bauplan: Gnomenkampfhuhn", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGnomen-Kampfhuhn\nWird beim Aufheben gebunden\nSchmuck\nBenötigt Ingenieurskunst (230)\nBenutzen: Erschafft ein Kampfhuhn, dass für 1.50 Min. oder bis es zerstört wird, für euch kämpfen wird. (30 Min Abklingzeit)\nBenötigt Mithrilgehäuse , Echtsilberbarren (6), Mithrilbarren (6), Veredelter Mithrilzylinder (2), Goldkraftkern , Jade (2)" }
entries[221333] = { ["name"] = "Bauplan: Gnomische Gedankenkontrollkappe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGnomen-Gedankenkontrollkappe\nWird beim Anlegen gebunden\nKopf Stoff\n50 Rüstung\n+14 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (215)\nBenutzen: Beginnt einen mentalen Kampf gegen ein humanoides Ziel und versucht, Kontrolle über dessen Gedanken zu erlangen. Wenn alles gut geht, werdet Ihr die Gedanken des Ziels 20 Sek. lang kontrollieren... (30 Min Abklingzeit)\nBenötigt Mithrilbarren (10), Echtsilberbarren (4), Goldkraftkern , Sternrubin (2), Magiestoff (4)" }
entries[221334] = { ["name"] = "Bauplan: Gnomentodesstrahl", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGnomentodesstrahl\nWird beim Aufheben gebunden\nSchmuck\nBenutzen: Der Todesstrahl benötigt einige Zeit, um sich mit Eurer Lebenskraft aufzuladen und feuert Â dann einen Energiestoß auf Euren Gegner ab. (5 Min Abklingzeit)\n\"Verwendung dieses Geräts kann zum Tod oder zu schweren Verletzungen führen.\"\nBenötigt Mithrilrohr (2), Instabiler Auslöser , Essenz des Untodes , Sekret des Untodes (4), Veredelter Mithrilzylinder" }
entries[221335] = { ["name"] = "Bauplan: Goblinschutzhelm", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGoblinscher Schutzhelm\nWird beim Aufheben gebunden\nKopf Stoff\n44 Rüstung\n+15 Feuerwiderstand\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (205)\nBenutzen: Absorbiert 300 bis 500 Punkt(e) Feuerschaden. Hält 1 Min. lang an. (1 Stunde Abklingzeit)\nBenötigt Mithrilbarren (8), Citrin , Elementarfeuer (4)" }
entries[221336] = { ["name"] = "Bauplan: Goblinbergbauhelm", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGoblin-Bergbauhelm\nWird beim Aufheben gebunden\nKopf Kette\n190 Rüstung\n+15 Ausdauer\nHaltbarkeit 60 / 60\nBenötigt Ingenieurskunst (205)\nAnlegen: Bergbau +5.\nBenötigt Mithrilbarren (8), Citrin , Elementarerde (4)" }
entries[221337] = { ["name"] = "Bauplan: Goblinmörser", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGoblin-Mörser\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst (205)\nBenutzen: Fügt 383 bis 517 Punkt(e) Feuerschaden zu und betäubt 3 Sek. lang die Ziele in einem Umkreis von 5 Metern. (10 Min Abklingzeit)\n6 Aufladungen\nBenötigt Mithrilrohr (2), Mithrilbarren (4), Robustes Sprengpulver (5), Goldkraftkern , Elementarfeuer" }
entries[221338] = { ["name"] = "Bauplan: Goblinpioniersprengladung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGoblinsche Pioniersprengladung\nBenötigt Ingenieurskunst (205)\nBenutzen: Explodiert bei Auslösung und verursacht 450 bis 750 Punkt(e) Feuerschaden bei allen in der Nähe befindlichen feindlichen Einheiten und 375 bis 625 Punkt(e) Schaden bei Euch. (5 Min Abklingzeit)\nBenötigt Magiestoff , Robustes Sprengpulver (3), Instabiler Auslöser" }
entries[221339] = { ["name"] = "Bauplan: Goblinraketenstiefel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGoblin-Raketenstiefel\nWird beim Anlegen gebunden\nFüße Stoff\n41 Rüstung\nHaltbarkeit 35 / 35\nBenutzen: Diese gefährlich aussehenden Stiefel erhöhen Euer Lauftempo 20 Sek. lang erheblich. Sie explodieren allerdings leicht, sind also mit Vorsicht zu verwenden. (5 Min Abklingzeit)\nBenötigt Schwarze Magiestoffstiefel , Mithrilrohr (2), Schweres Leder (4), Goblin-Raketentreibstoff (2), Instabiler Auslöser" }
entries[221340] = { ["name"] = "Bauplan: Goblinbombenspender", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGoblin-Bombenspender\nWird beim Aufheben gebunden\nSchmuck\nBenötigt Ingenieurskunst (230)\nBenutzen: Lässt eine mobile Bombe entstehen, die den nächstbefindlichen Feind angreift, explodiert und dabei 315 bis 385 Punkt(e) Feuerschaden verursacht. (30 Min Abklingzeit)\nBenötigt Mithrilgehäuse (2), Robustes Sprengpulver (4), Echtsilberbarren (6), Instabiler Auslöser , Genaues Zielfernrohr (2)" }
entries[221341] = { ["name"] = "Bauplan: Die Große", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nDer Große\nBenötigt Ingenieurskunst (225)\nBenutzen: Fügt 340 bis 460 Feuerschaden zu und betäubt Ziele 5 Sek. lang in einem Umkreis von 10 Metern. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)\nBenötigt Mithrilgehäuse , Goblin-Raketentreibstoff , Robustes Dynamit (6), Instabiler Auslöser" }
entries[221342] = { ["name"] = "Bauplan: Goblindrachengewehr", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGoblinscher Drachenwerfer\nWird beim Aufheben gebunden\nSchmuck\nBenutzen: Fügt jedem Feind in einem Kegel vor dem Ingenieur, der die Waffe benutzt, 10 Sek. lang 61 bis 69 Punkt(e) Feuerschaden zu. Es sei denn, sie explodiert... (5 Min Abklingzeit)\nBenötigt Mithrilrohr (2), Goblin-Raketentreibstoff (4), Mithrilbarren (6), Echtsilberbarren (6), Instabiler Auslöser" }
entries[221343] = { ["name"] = "Bauplan: Goblinraketenhelm", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (205)\nBenutzen:\n\nGoblin-Raketenhelm\nWird beim Anlegen gebunden\nKopf Stoff\n50 Rüstung\n+15 Ausdauer\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (235)\nBenutzen: Einen Feind attackieren und ihn für 30 Sekunden außer Gefecht setzen. Ihr werdet ebenfalls niedergeschlagen und für kurze Zeit betäubt. Jeglicher erlittener Schaden wird das Ziel wiederbeleben. (20 Min Abklingzeit)\nBenötigt Goblinscher Schutzhelm , Goblin-Raketentreibstoff (4), Mithrilbarren (4), Instabiler Auslöser" }
entries[221344] = { ["name"] = "Persönliches Zauberbuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nIn Schildhand geführt\nKlassen: Magier\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nBenutzen: Beschwört 5 Verständnisamulette. (4 Std. Abklingzeit)" }
entries[221345] = { ["name"] = "Verderbtes Blut des Eranikus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 50" }
entries[221346] = { ["name"] = "Schulterblatt des gefallenen Avatars", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 50\n\"Ein gut erhaltenes, wunderschön geformtes Schulterblatt, das keine Schäden aufweist.\"" }
