entries[221350] = { ["name"] = "Verkohlte Notizen des Schamanen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Schamane\n\"Die Seiten sind bis zur Unleserlichkeit verkohlt. Sie scheinen um etwas anderes gewickelt zu sein.\"" }
entries[221351] = { ["name"] = "Durchnässte Notizen des Schamanen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Schamane\n\"Wasser hat die Tinte unleserlich gemacht. Die Seiten scheinen um etwas anderes gewickelt zu sein.\"" }
