entries[221362] = { ["name"] = "Waffenreinigungstuch", ["text"] = "BenötigtSmaragdwärter\n- Freundlich\nBenutzen: Reinigt Eure Waffe. Alle zeitlich begrenzten Verzauberungen werden entfernt. So gut wie neu!" }
