entries[221364] = { ["name"] = "Kupfermassakermünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Transmutiert 100 Kupfermassakermünzen in 1 Silbermassakermünze.\n\"Ein Zeichen für Eure bescheidenen Dienste für den Blutloa.\"" }
entries[221365] = { ["name"] = "Silbermassakermünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Transmutiert 100 Silbermassakermünzen in 1 Goldmassakermünze.\n\"Ein Zeichen für Eure Dienste für den Blutloa.\"" }
