entries[221369] = { ["name"] = "Alptraumsog", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 20\nBenötigtSmaragdwärter\n- Freundlich\nAnlegen: Stellt 150 Gesundheit und Mana wieder her, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt. Dieser Effekt kann nur einmal alle 10 Sek. auftreten. (10s Abklingzeit)" }
entries[221370] = { ["name"] = "Wertvolles Medaillon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Auf der Rückseite steht: 'Stupser + Enie'\"" }
entries[221371] = { ["name"] = "Münzbeutel des Entführers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Öffnen rechtsklicken>" }
entries[221372] = { ["name"] = "Zerfetzter Münzbeutel", ["text"] = "\"Der Inhalt wurde wahrscheinlich im Kampf beschädigt.\"" }
entries[221374] = { ["name"] = "Qual des Traums", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 30\nBenötigtSmaragdwärter\n- Freundlich\nAnlegen: Erhöht den Schaden oder die Heilung Eures nächsten Angriffs, Eurer nächsten Fähigkeit oder Eures nächsten Zaubers um 40, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt. Dieser Effekt kann nur einmal alle 10 Sek. auftreten. (10s Abklingzeit)" }
entries[221376] = { ["name"] = "Helm des Smaragdgrünen Traums", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n429 Rüstung\n+10 Stärke\n+11 Ausdauer\nHaltbarkeit 80 / 80\nKlassen: Krieger , Paladin\nBenötigt Stufe 50\nBenötigtSmaragdwärter\n- Wohlwollend\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n\nPlattenrüstung des Smaragdgrünen Traums (0/6)\nSchulterstücke des Smaragdgrünen Traums\nBrustplatte des Smaragdgrünen Traums\nSabatons des Smaragdgrünen Traums\nStulpen des Smaragdgrünen Traums\nBeinplatten des Smaragdgrünen Traums\nHelm des Smaragdgrünen Traums\n(3) Set : +10 Ausdauer.\n(6) Set : +20 Angriffskraft." }
