entries[221439] = { ["name"] = "Rüstung des Smaragdschlummers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBrust Leder\n146 Rüstung\n+22 Ausdauer\n+5 Arkanwiderstand\n+5 Naturwiderstand\nHaltbarkeit 100 / 100\nBenötigt Stufe 50\nBenötigtSmaragdwärter\n- Respektvoll\nAnlegen: Bei einem Treffer durch einen Nahkampfangreifer hat dieser Angreifer eine Chance von 5%, 10 Sek. lang in Schlaf versetzt zu werden. Wirkt nur bei Gegnern der Stufe 50 oder niedriger. (Procchance: 5%)" }
entries[221440] = { ["name"] = "Gebrüll des Traums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+14 Ausdauer\nBenötigt Stufe 50\nBenötigtSmaragdwärter\n- Ehrfürchtig\nAnlegen: Eure Offensivzauber haben eine Chance, Euren Zauberschaden 10 Sek. lang um 66 zu erhöhen. (Procchance: 5%)" }
entries[221441] = { ["name"] = "Wächter des Traums", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n60 - 94 Schaden Tempo 2.00\n(38.50 Schaden pro Sekunde)\n+18 Stärke\n+14 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 43\nBenötigtSmaragdwärter\n- Respektvoll\nAnlegen: +73 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt." }
entries[221442] = { ["name"] = "Gebrüll des Wächters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n+10 Ausdauer\nBenötigt Stufe 50\nBenötigtSmaragdwärter\n- Ehrfürchtig\nBenutzen: Erhöht die Nahkampf- und Distanzangriffskraft 20 Sek. lang um 70. (2 Min Abklingzeit)" }
entries[221443] = { ["name"] = "Gebrüll des Hains", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n+10 Ausdauer\nBenötigt Stufe 50\nBenötigtSmaragdwärter\n- Ehrfürchtig\nBenutzen: Ruft die Macht des Traums an, die 15 Sek. lang bestehen bleibt. Während der Zaubernde in diesem Kreis steht, erhält er 120 Heilkraft. (2 Min Abklingzeit)" }
entries[221444] = { ["name"] = "Dschungeldurian", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 3222 Gesundheit und 6618 Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Wenn man den widerlichen Gestank aushalten kann, ist diese Frucht ganz lecker!\"" }
entries[221445] = { ["name"] = "Rune des fokussierten Feuers", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nPrägt Eure Armschienen mit der Rune 'Fokussiertes Feuer':\n\nVerbraucht alle Anwendungen von 'Raserei' auf Eurem Tier, was Eurer Distanzangriffstempo um 3% erhöht und Eurem Tier 4 Fokus für jede verbrauchte Anwendung von 'Raserei' verleiht. Hält 20 Sek. lang an.\n\nImmer wenn Euer Tier einen einfachen Angriff ausführt, erhält es 'Raserei', und sein Nahkampfangriffstempo wird 10 Sek. lang um 6% erhöht. Bis zu 5-mal stapelbar.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221446] = { ["name"] = "Hammer des Ritualisten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nZweihändig Streitkolben\n108 - 173 Schaden Tempo 3.00\n(46.83 Schaden pro Sekunde)\n+11 Stärke\n+15 Beweglichkeit\n+30 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Druide\nBenötigt Stufe 50\nAnlegen: +114 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\nBenutzen: Verleiht Euren Nahkampfangriffen zusätzlich 5 Sturmschlagschaden, der das Ziel und dessen nächsten Verbündeten trifft. Wirkt sich auf bis zu 3 Ziele aus. Verursacht zusätzliche Bedrohung. Hält 20 Sek. lang an. (3 Min Abklingzeit)" }
entries[221447] = { ["name"] = "Zauberfoliant des Blutmondritualisten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nIn Schildhand geführt\n+14 Ausdauer\n+5 Intelligenz\nKlassen: Druide\nBenötigt Stufe 50\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 16." }
entries[221448] = { ["name"] = "Talisman des verderbten Hains", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nSchmuck\n+8 Ausdauer\nKlassen: Druide\nBenötigt Stufe 50\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 29.\nAnlegen: Stellt alle 5 Sek. 7 Punkt(e) Mana wieder her." }
entries[221450] = { ["name"] = "Grubenkämpferbogen der Gurubashi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nDistanz Bogen\n39 - 72 Schaden Tempo 1.80\n(30.83 Schaden pro Sekunde)\nHaltbarkeit 95 / 95\nKlassen: Jäger\nBenötigt Stufe 50\nAnlegen: Bei einem Treffer besteht eine Chance, die Stärke 15 Sek. lang um 75 zu erhöhen. (Procchance: 5%)" }
entries[221451] = { ["name"] = "Armbrust des Blutdursts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nDistanz Armbrust\n77 - 115 Schaden Tempo 3.10\n(30.97 Schaden pro Sekunde)\n+6 Beweglichkeit\n+6 Ausdauer\nHaltbarkeit 90 / 90\nKlassen: Jäger\nBenötigt Stufe 50\nAnlegen: Eure Distanzangriffe entziehen Zielen 5 Gesundheit." }
entries[221452] = { ["name"] = "Blutfokussiertes Arkanband", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nFinger\n+14 Ausdauer\n+4 Intelligenz\nKlassen: Magier\nBenötigt Stufe 50\nAnlegen: Erhöht durch Arkanzauber und Arkaneffekte zugefügten Schaden um bis zu 17." }
